theorem p5_counterexample :
    let A : Finset (Fin 5) := Finset.univ.filter (fun v => P5.degree v = P5.minDegree)
    let M : Finset (Fin 5) := Finset.univ.filter (fun v => P5.degree v = P5.maxDegree)
    let distavgA : ℝ := (∑ p ∈ A.offDiag, (P5.dist p.1 p.2 : ℝ)) / (A.offDiag.card : ℝ)
    let eccavg (S : Finset (Fin 5)) : ℝ :=
      (∑ v ∈ S, (P5.eccent v).toNat) / (S.card : ℝ)
    ¬ (distavgA + (1 / 2 : ℝ) * eccavg M ≤ (path P5 : ℝ))

theorem conjecture32 : False ↔
    ∀ (α : Type) [Fintype α] [DecidableEq α] [Nontrivial α]
      (G : SimpleGraph α) [DecidableRel G.Adj] (_h : G.Connected),
      let A : Finset α := Finset.univ.filter (fun v => G.degree v = G.minDegree)
      let M : Finset α := Finset.univ.filter (fun v => G.degree v = G.maxDegree)
      let distavgA : ℝ := (∑ p ∈ A.offDiag, (G.dist p.1 p.2 : ℝ)) / (A.offDiag.card : ℝ)
      let eccavg (S : Finset α) : ℝ := (∑ v ∈ S, (G.eccent v).toNat) / (S.card : ℝ)
      distavgA + (1 / 2 : ℝ) * eccavg M ≤ (path G : ℝ)

lemma induce_insert_adj {G : SimpleGraph α} {s : Set α} {u v : α}
    (hs : (G.induce s).Connected) (hu : u ∈ s) (huv : G.Adj u v) :
    (G.induce (insert v s)).Connected

lemma induce_star_connected {G : SimpleGraph α} {c : α} {S : Finset α}
    (hS : ∀ s ∈ S, G.Adj c s) :
    (G.induce (insert c S : Set α)).Connected

lemma feasible_extend (G : SimpleGraph α) [DecidableRel G.Adj] {μ : ℕ} {M T : Finset α}
    (hF : Feasible G μ M T) {u v : α}
    (huN : ∃ m ∈ M, G.Adj m u) (hvout : v ∉ closedN G M) (huv : G.Adj u v) :
    Feasible G μ (insert v M) (insert v (insert u T))

private lemma dist_le_mem_iterate_bfsStep (G : SimpleGraph α) [DecidableRel G.Adj]
    (u w : α) (n : ℕ) (hdist : G.dist u w ≤ n) (hreach : w = u ∨ G.Reachable u w) :
    w ∈ G.bfsStep^[n] {u}
